function validate([players, trainers]) {
  if (players.length < 1 || players.length > 100000) return 'players needs 1 to 10^5 values.';
  if (trainers.length < 1 || trainers.length > 100000) return 'trainers needs 1 to 10^5 values.';
  if (players.some(v => v < 1 || v > 1000000000)) return 'Each player value is between 1 and 10^9.';
  if (trainers.some(v => v < 1 || v > 1000000000)) return 'Each trainer value is between 1 and 10^9.';
  return null;
}

