function matchPlayersAndTrainers(players, trainers) {
  players.sort((a, b) => a - b);
  trainers.sort((a, b) => a - b);
  let player = 0;
  let trainer = 0;
  while (player < players.length && trainer < trainers.length) {
    if (players[player] <= trainers[trainer]) {
      player++;
    }
    trainer++;
  }
  return player;
}

