function matchPlayersAndTrainers(players, trainers) {
  // Maximum bipartite matching with augmenting paths (Kuhn's algorithm).
  const owner = new Array(trainers.length).fill(-1);
  const tryPlayer = (p, seen) => {
    for (let t = 0; t < trainers.length; t++) {
      if (players[p] > trainers[t] || seen[t]) continue;
      seen[t] = true;
      if (owner[t] === -1 || tryPlayer(owner[t], seen)) { owner[t] = p; return true; }
    }
    return false;
  };
  let count = 0;
  for (let p = 0; p < players.length; p++) if (tryPlayer(p, new Array(trainers.length).fill(false))) count++;
  return count;
}

