function generate(rand, size) {
  if (size === 'large') {
    const make = (n) => Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000000));
    return [make(1500 + Math.floor(rand() * 501)), make(1500 + Math.floor(rand() * 501))];
  }
  const top = rand() < 0.8 ? 10 : 1000000000;
  const make = () => Array.from({ length: 1 + Math.floor(rand() * 7) }, () => 1 + Math.floor(rand() * top));
  return [make(), make()];
}
